'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import axios from 'axios'
import toast from 'react-hot-toast'
import { 
  HomeIcon,
  DocumentTextIcon,
  ArrowDownTrayIcon,
  ArrowUpTrayIcon,
  TrashIcon,
  ArrowPathIcon,
  CloudArrowDownIcon,
  CloudArrowUpIcon,
  ShieldCheckIcon
} from '@heroicons/react/24/outline'

const API_BASE_URL = 'http://localhost:5000/api'

export default function BackupPage() {
  const router = useRouter()
  const [loading, setLoading] = useState(false)
  const [backups, setBackups] = useState([])
  const [restoreFile, setRestoreFile] = useState(null)
  const [creatingBackup, setCreatingBackup] = useState(false)

  useEffect(() => {
    checkAuth()
    fetchBackups()
  }, [])

  const checkAuth = () => {
    const user = localStorage.getItem('user')
    if (!user) {
      router.push('/')
    }
  }

  const fetchBackups = async () => {
    try {
      setLoading(true)
      const response = await axios.get(`${API_BASE_URL}/backup/list`)
      setBackups(response.data.backups || [])
    } catch (error) {
      console.error('Error fetching backups:', error)
      toast.error('Failed to fetch backups')
    } finally {
      setLoading(false)
    }
  }

  const createBackup = async () => {
    try {
      setCreatingBackup(true)
      const response = await axios.post(`${API_BASE_URL}/backup/create`)
      if (response.data.success) {
        toast.success('Backup created successfully!')
        fetchBackups()
      }
    } catch (error) {
      console.error('Error creating backup:', error)
      toast.error('Failed to create backup')
    } finally {
      setCreatingBackup(false)
    }
  }

  const downloadBackup = async (filename) => {
    try {
      const response = await axios.get(`${API_BASE_URL}/backup/download/${filename}`, {
        responseType: 'blob'
      })

      const url = window.URL.createObjectURL(new Blob([response.data]))
      const link = document.createElement('a')
      link.href = url
      link.setAttribute('download', filename)
      document.body.appendChild(link)
      link.click()
      link.remove()
      window.URL.revokeObjectURL(url)

      toast.success('Backup downloaded successfully!')
    } catch (error) {
      console.error('Error downloading backup:', error)
      toast.error('Failed to download backup')
    }
  }

  const restoreBackup = async () => {
    if (!restoreFile) {
      toast.error('Please select a backup file')
      return
    }

    if (!confirm('⚠️ WARNING: This will overwrite your current database! Make sure you have a recent backup. Continue?')) {
      return
    }

    const formData = new FormData()
    formData.append('file', restoreFile)

    try {
      setCreatingBackup(true)
      const response = await axios.post(`${API_BASE_URL}/backup/restore`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data'
        }
      })

      if (response.data.success) {
        toast.success('Database restored successfully!')
        fetchBackups()
        setRestoreFile(null)
        const fileInput = document.getElementById('restore-file')
        if (fileInput) fileInput.value = ''
      }
    } catch (error) {
      console.error('Error restoring backup:', error)
      toast.error('Failed to restore backup')
    } finally {
      setCreatingBackup(false)
    }
  }

  const deleteBackup = async (filename) => {
    if (!confirm(`Delete backup ${filename}? This action cannot be undone.`)) return

    try {
      const response = await axios.delete(`${API_BASE_URL}/backup/delete/${filename}`)
      if (response.data.success) {
        toast.success('Backup deleted successfully!')
        fetchBackups()
      }
    } catch (error) {
      console.error('Error deleting backup:', error)
      toast.error('Failed to delete backup')
    }
  }

  const formatFileSize = (sizeMB) => {
    if (sizeMB < 1) return `${(sizeMB * 1024).toFixed(2)} KB`
    return `${sizeMB.toFixed(2)} MB`
  }

  const formatDate = (dateString) => {
    if (!dateString) return '-'
    const date = new Date(dateString)
    return date.toLocaleString('en-IN', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const goToDashboard = () => {
    router.push('/dashboard')
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-pink-900">
      <div className="absolute inset-0 bg-black/30 backdrop-blur-[2px]" />

      <div className="relative">
        {/* Header */}
        <header className="bg-white/10 backdrop-blur-xl border-b border-white/20 sticky top-0 z-10">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <button
                  onClick={goToDashboard}
                  className="p-2 bg-white/10 border border-white/20 rounded-lg text-white hover:bg-white/20"
                  title="Back to Dashboard"
                >
                  <HomeIcon className="h-5 w-5" />
                </button>
                <div>
                  <h1 className="text-2xl font-bold text-white">
                    Backup & Restore
                  </h1>
                  <p className="text-white/60 text-sm">Protect your data with automated backups</p>
                </div>
              </div>
              <button
                onClick={createBackup}
                disabled={creatingBackup}
                className="px-4 py-2 bg-green-500/20 border border-green-500/30 
                  rounded-lg text-green-400 hover:bg-green-500/30
                  flex items-center gap-2 disabled:opacity-50"
              >
                <CloudArrowUpIcon className="h-4 w-4" />
                {creatingBackup ? 'Creating...' : 'Create Backup'}
              </button>
            </div>
          </div>
        </header>

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {/* Info Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
            <div className="bg-gradient-to-br from-blue-500/10 to-cyan-500/10 backdrop-blur-xl border border-white/20 rounded-xl p-4">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-blue-500/20 rounded-lg">
                  <ShieldCheckIcon className="h-6 w-6 text-blue-400" />
                </div>
                <div>
                  <p className="text-white/60 text-xs">Backup Location</p>
                  <p className="text-white font-semibold text-sm">/backups/ folder</p>
                </div>
              </div>
            </div>

            <div className="bg-gradient-to-br from-green-500/10 to-emerald-500/10 backdrop-blur-xl border border-white/20 rounded-xl p-4">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-green-500/20 rounded-lg">
                  <DocumentTextIcon className="h-6 w-6 text-green-400" />
                </div>
                <div>
                  <p className="text-white/60 text-xs">Total Backups</p>
                  <p className="text-white font-bold text-2xl">{backups.length}</p>
                </div>
              </div>
            </div>

            <div className="bg-gradient-to-br from-purple-500/10 to-pink-500/10 backdrop-blur-xl border border-white/20 rounded-xl p-4">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-purple-500/20 rounded-lg">
                  <ArrowDownTrayIcon className="h-6 w-6 text-purple-400" />
                </div>
                <div>
                  <p className="text-white/60 text-xs">Latest Backup</p>
                  <p className="text-white font-semibold text-sm">
                    {backups.length > 0 ? formatDate(backups[0].created) : 'No backups'}
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Restore Section */}
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6 mb-6">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <CloudArrowDownIcon className="h-5 w-5 text-yellow-400" />
              Restore from Backup
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-white/80 text-sm mb-2">Select Backup File (.zip)</label>
                <input
                  id="restore-file"
                  type="file"
                  accept=".zip"
                  onChange={(e) => setRestoreFile(e.target.files[0])}
                  className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white
                    file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0
                    file:text-sm file:font-semibold file:bg-pink-500 file:text-white
                    hover:file:bg-pink-600"
                />
              </div>
              <div className="flex items-end">
                <button
                  onClick={restoreBackup}
                  disabled={!restoreFile || creatingBackup}
                  className="px-6 py-2 bg-yellow-500/20 border border-yellow-500/30 
                    rounded-lg text-yellow-400 hover:bg-yellow-500/30
                    flex items-center gap-2 disabled:opacity-50"
                >
                  <ArrowUpTrayIcon className="h-4 w-4" />
                  Restore Database
                </button>
              </div>
            </div>
            <p className="text-white/50 text-xs mt-3">
              ⚠️ Warning: Restoring will overwrite your current database. Please ensure you have a recent backup before restoring.
            </p>
          </div>

          {/* Backups List */}
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
            <h2 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
              <DocumentTextIcon className="h-5 w-5 text-green-400" />
              Available Backups
            </h2>

            {loading ? (
              <div className="text-center py-8">
                <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-white border-r-transparent"></div>
                <p className="text-white/70 mt-2">Loading backups...</p>
              </div>
            ) : backups.length === 0 ? (
              <div className="text-center py-12">
                <ShieldCheckIcon className="h-12 w-12 text-white/20 mx-auto mb-3" />
                <p className="text-white/50">No backups found</p>
                <p className="text-white/30 text-sm mt-1">Click "Create Backup" to protect your data</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead className="bg-white/5">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-medium text-white/60">Filename</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-white/60">Created</th>
                      <th className="px-4 py-3 text-right text-xs font-medium text-white/60">Size</th>
                      <th className="px-4 py-3 text-center text-xs font-medium text-white/60">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-white/10">
                    {backups.map((backup, index) => (
                      <tr key={index} className="hover:bg-white/5 transition-colors">
                        <td className="px-4 py-3 text-sm text-white font-mono">{backup.filename}</td>
                        <td className="px-4 py-3 text-sm text-white/70">{formatDate(backup.created)}</td>
                        <td className="px-4 py-3 text-sm text-white/70 text-right">{formatFileSize(backup.size_mb)}</td>
                        <td className="px-4 py-3 text-sm text-center">
                          <div className="flex items-center justify-center gap-2">
                            <button
                              onClick={() => downloadBackup(backup.filename)}
                              className="p-1 text-blue-400 hover:text-blue-300 hover:bg-white/10 rounded transition-colors"
                              title="Download"
                            >
                              <ArrowDownTrayIcon className="h-4 w-4" />
                            </button>
                            <button
                              onClick={() => deleteBackup(backup.filename)}
                              className="p-1 text-red-400 hover:text-red-300 hover:bg-white/10 rounded transition-colors"
                              title="Delete"
                            >
                              <TrashIcon className="h-4 w-4" />
                            </button>
                          </div>
                        </td>
                       </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </main>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import axios from 'axios'
import toast from 'react-hot-toast'
import { 
  PencilIcon, 
  TrashIcon, 
  PlusIcon,
  MagnifyingGlassIcon,
  BuildingLibraryIcon
} from '@heroicons/react/24/outline'

export default function BanksPage() {
  const [banks, setBanks] = useState([])
  const [loading, setLoading] = useState(true)
  const [showModal, setShowModal] = useState(false)
  const [editingBank, setEditingBank] = useState(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [formData, setFormData] = useState({
    name: '',
    account_no: '',
    ifsc_code: '',
    branch: '',
    opening_balance: 0
  })

  const router = useRouter()

  useEffect(() => {
    checkAuth()
    fetchBanks()
  }, [])

  const checkAuth = () => {
    const user = localStorage.getItem('user')
    if (!user) {
      router.push('/')
    }
  }

  const fetchBanks = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/banks/')
      setBanks(response.data)
    } catch (error) {
      toast.error('Failed to fetch banks')
    } finally {
      setLoading(false)
    }
  }

  const handleInputChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    try {
      console.log('Submitting bank data:', formData)
      
      if (editingBank) {
        // Update
        const response = await axios.put(`http://localhost:5000/api/banks/${editingBank.id}`, formData)
        console.log('Update response:', response.data)
        toast.success('Bank updated successfully')
      } else {
        // Create
        const response = await axios.post('http://localhost:5000/api/banks/', formData)
        console.log('Create response:', response.data)
        toast.success('Bank added successfully')
      }
      
      setShowModal(false)
      resetForm()
      fetchBanks()
    } catch (error) {
      console.error('Error details:', error.response?.data || error.message)
      toast.error('Operation failed: ' + (error.response?.data?.error || error.message))
    }
  }

  const handleEdit = (bank) => {
    setEditingBank(bank)
    setFormData({
      name: bank.name || '',
      account_no: bank.account_no || '',
      ifsc_code: bank.ifsc_code || '',
      branch: bank.branch || '',
      opening_balance: bank.opening_balance || 0
    })
    setShowModal(true)
  }

  const handleDelete = async (id) => {
    if (confirm('Are you sure you want to delete this bank?')) {
      try {
        await axios.delete(`http://localhost:5000/api/banks/${id}`)
        toast.success('Bank deleted successfully')
        fetchBanks()
      } catch (error) {
        toast.error('Delete failed')
      }
    }
  }

  const resetForm = () => {
    setEditingBank(null)
    setFormData({
      name: '',
      account_no: '',
      ifsc_code: '',
      branch: '',
      opening_balance: 0
    })
  }

  const filteredBanks = banks.filter(bank =>
    bank.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    bank.code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    bank.account_no?.includes(searchTerm) ||
    bank.branch?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0
    }).format(amount)
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-pink-900">
      {/* Background */}
      <div className="absolute inset-0 bg-black/30 backdrop-blur-[2px]" />
      
      {/* Content */}
      <div className="relative">
        {/* Header */}
        <header className="bg-white/10 backdrop-blur-xl border-b border-white/20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <BuildingLibraryIcon className="h-8 w-8 text-pink-400" />
                <h1 className="text-2xl font-bold text-white">
                  BANK MASTER
                </h1>
              </div>
              <button
                onClick={() => router.push('/dashboard')}
                className="px-4 py-2 bg-white/10 border border-white/20 
                  rounded-lg text-white hover:bg-white/20
                  transition-all duration-200"
              >
                ← Back to Dashboard
              </button>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {/* Actions Bar */}
          <div className="flex flex-col sm:flex-row gap-4 justify-between mb-6">
            {/* Search */}
            <div className="relative flex-1 max-w-md">
              <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-white/50" />
              <input
                type="text"
                placeholder="Search banks by name, code, account, branch..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white/10 border border-white/20 
                  rounded-lg text-white placeholder-white/50
                  focus:outline-none focus:ring-2 focus:ring-pink-500"
              />
            </div>
            
            {/* Add Button */}
            <button
              onClick={() => {
                resetForm()
                setShowModal(true)
              }}
              className="px-4 py-2 bg-gradient-to-r from-green-500 to-emerald-600
                text-white rounded-lg hover:from-green-600 hover:to-emerald-700
                flex items-center justify-center gap-2"
            >
              <PlusIcon className="h-5 w-5" />
              Add Bank
            </button>
          </div>

          {/* Banks Table */}
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-white/5">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Code</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Bank Name</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Account No</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">IFSC Code</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Branch</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Balance</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/10">
                  {filteredBanks.map((bank) => (
                    <tr key={bank.id} className="hover:bg-white/5 transition-colors">
                      <td className="px-6 py-4 text-sm text-white font-mono">{bank.code}</td>
                      <td className="px-6 py-4 text-sm text-white font-medium">{bank.name}</td>
                      <td className="px-6 py-4 text-sm text-white/70">{bank.account_no}</td>
                      <td className="px-6 py-4 text-sm text-white/70">{bank.ifsc_code}</td>
                      <td className="px-6 py-4 text-sm text-white/70">{bank.branch}</td>
                      <td className="px-6 py-4 text-sm text-green-400 font-semibold">
                        {formatCurrency(bank.current_balance || bank.opening_balance)}
                      </td>
                      <td className="px-6 py-4 text-sm">
                        <button
                          onClick={() => handleEdit(bank)}
                          className="text-blue-400 hover:text-blue-300 mr-3 transition-colors"
                          title="Edit Bank"
                        >
                          <PencilIcon className="h-5 w-5 inline" />
                        </button>
                        <button
                          onClick={() => handleDelete(bank.id)}
                          className="text-red-400 hover:text-red-300 transition-colors"
                          title="Delete Bank"
                        >
                          <TrashIcon className="h-5 w-5 inline" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            
            {/* Empty State */}
            {filteredBanks.length === 0 && (
              <div className="text-center py-16">
                <BuildingLibraryIcon className="h-16 w-16 text-white/20 mx-auto mb-4" />
                <p className="text-white/50 text-lg">No banks found</p>
                <p className="text-white/30 text-sm mt-2">Click "Add Bank" to create your first bank account</p>
              </div>
            )}
          </div>

          {/* Summary Card */}
          {banks.length > 0 && (
            <div className="mt-6 bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-4">
              <div className="flex justify-between items-center">
                <span className="text-white/70">Total Banks:</span>
                <span className="text-white font-semibold">{banks.length}</span>
                <span className="text-white/70">Total Balance:</span>
                <span className="text-green-400 font-semibold">
                  {formatCurrency(banks.reduce((sum, bank) => sum + (bank.current_balance || bank.opening_balance || 0), 0))}
                </span>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Bank Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6 w-full max-w-lg max-h-[90vh] overflow-y-auto">
            <div className="flex items-center gap-3 mb-4">
              <BuildingLibraryIcon className="h-6 w-6 text-pink-400" />
              <h2 className="text-xl font-semibold text-white">
                {editingBank ? 'Edit Bank' : 'Add New Bank'}
              </h2>
            </div>
            
            <form onSubmit={handleSubmit} className="space-y-4">
              {/* Bank Name */}
              <div>
                <label className="block text-white/80 text-sm mb-1">Bank Name *</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  required
                  className="w-full px-3 py-2 bg-white/10 border border-white/20 
                    rounded-lg text-white placeholder-white/50
                    focus:outline-none focus:ring-2 focus:ring-pink-500"
                  placeholder="e.g., HDFC Bank"
                />
              </div>
              
              {/* Account Number */}
              <div>
                <label className="block text-white/80 text-sm mb-1">Account Number *</label>
                <input
                  type="text"
                  name="account_no"
                  value={formData.account_no}
                  onChange={handleInputChange}
                  required
                  className="w-full px-3 py-2 bg-white/10 border border-white/20 
                    rounded-lg text-white placeholder-white/50
                    focus:outline-none focus:ring-2 focus:ring-pink-500"
                  placeholder="Enter account number"
                />
              </div>
              
              {/* IFSC Code */}
              <div>
                <label className="block text-white/80 text-sm mb-1">IFSC Code *</label>
                <input
                  type="text"
                  name="ifsc_code"
                  value={formData.ifsc_code}
                  onChange={handleInputChange}
                  required
                  className="w-full px-3 py-2 bg-white/10 border border-white/20 
                    rounded-lg text-white placeholder-white/50
                    focus:outline-none focus:ring-2 focus:ring-pink-500"
                  placeholder="e.g., HDFC0001234"
                />
              </div>
              
              {/* Branch */}
              <div>
                <label className="block text-white/80 text-sm mb-1">Branch</label>
                <input
                  type="text"
                  name="branch"
                  value={formData.branch}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 bg-white/10 border border-white/20 
                    rounded-lg text-white placeholder-white/50
                    focus:outline-none focus:ring-2 focus:ring-pink-500"
                  placeholder="e.g., Mumbai Main"
                />
              </div>
              
              {/* Opening Balance - FIXED: Removed step validation */}
              <div>
                <label className="block text-white/80 text-sm mb-1">Opening Balance (₹)</label>
                <input
                  type="number"
                  name="opening_balance"
                  value={formData.opening_balance}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 bg-white/10 border border-white/20 
                    rounded-lg text-white placeholder-white/50
                    focus:outline-none focus:ring-2 focus:ring-pink-500"
                  placeholder="0"
                  min="0"
                  step="any"  // Changed to "any" to allow decimal values
                />
              </div>
              
              {/* Form Actions */}
              <div className="flex justify-end space-x-3 mt-6 pt-4 border-t border-white/10">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="px-4 py-2 bg-white/10 border border-white/20 
                    rounded-lg text-white hover:bg-white/20
                    transition-all duration-200"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-gradient-to-r from-pink-500 to-purple-600
                    text-white rounded-lg hover:from-pink-600 hover:to-purple-700
                    transition-all duration-200 font-medium"
                >
                  {editingBank ? 'Update Bank' : 'Save Bank'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import axios from 'axios'
import toast from 'react-hot-toast'
import {
  PencilIcon,
  TrashIcon,
  PlusIcon,
  MagnifyingGlassIcon,
  CubeIcon,
  BeakerIcon,
  ChevronDownIcon
} from '@heroicons/react/24/outline'

export default function ItemsPage() {
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [showModal, setShowModal] = useState(false)
  const [editingItem, setEditingItem] = useState(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [filterType, setFilterType] = useState('all') // 'all', 'raw_material', 'finished_good'
  const [formData, setFormData] = useState({
    item_type: 'raw_material',
    name: '',
    category: '',
    unit: 'KG',
    hsn_code: '',
    gst_rate: 18,
    purchase_rate: 0,
    sales_rate: 0,
    mrp: 0,
    opening_stock: 0,
    current_stock: 0,
    min_stock: 0,
    max_stock: 0,
    location: ''
  })

  const router = useRouter()

  useEffect(() => {
    checkAuth()
    fetchItems()
  }, [filterType])

  const checkAuth = () => {
    const user = localStorage.getItem('user')
    if (!user) {
      router.push('/')
    }
  }

  const fetchItems = async () => {
    try {
      const url = filterType === 'all' 
        ? 'http://localhost:5000/api/items/'
        : `http://localhost:5000/api/items/?type=${filterType}`
      
      const response = await axios.get(url)
      console.log('📦 Items API Response:', response.data)
      setItems(response.data)
    } catch (error) {
      toast.error('Failed to fetch items')
    } finally {
      setLoading(false)
    }
  }

  const handleInputChange = (e) => {
    const { name, value, type } = e.target
    setFormData(prev => ({ 
      ...prev, 
      [name]: type === 'number' ? parseFloat(value) || 0 : value 
    }))
  }

  const handleTypeChange = (e) => {
    const newType = e.target.value
    setFormData(prev => ({
      ...prev,
      item_type: newType,
      unit: newType === 'raw_material' ? 'KG' : 'PCS',
      purchase_rate: newType === 'raw_material' ? prev.purchase_rate : 0,
      sales_rate: newType === 'finished_good' ? prev.sales_rate : 0,
      mrp: newType === 'finished_good' ? prev.mrp : 0
    }))
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    
    try {
      console.log('📤 Submitting item data:', formData)
      
      // Prepare payload with all fields
      const payload = {
        ...formData,
        gst_rate: parseFloat(formData.gst_rate) || 18,
        purchase_rate: parseFloat(formData.purchase_rate) || 0,
        sales_rate: parseFloat(formData.sales_rate) || 0,
        mrp: parseFloat(formData.mrp) || 0,
        opening_stock: parseFloat(formData.opening_stock) || 0,
        current_stock: parseFloat(formData.current_stock) || 0,
        min_stock: parseFloat(formData.min_stock) || 0,
        max_stock: parseFloat(formData.max_stock) || 0
      }
      
      if (editingItem) {
        // Update
        const response = await axios.put(
          `http://localhost:5000/api/items/${editingItem.item_type}/${editingItem.id}`,
          payload
        )
        console.log('✅ Update response:', response.data)
        toast.success('Item updated successfully')
      } else {
        // Create
        const response = await axios.post('http://localhost:5000/api/items/', payload)
        console.log('✅ Create response:', response.data)
        toast.success('Item added successfully')
      }
      
      setShowModal(false)
      resetForm()
      fetchItems()
    } catch (error) {
      console.error('❌ Error:', error)
      toast.error('Operation failed: ' + (error.response?.data?.error || error.message))
    }
  }

  const handleEdit = (item) => {
    console.log('🖊️ Editing item:', item)
    console.log('📊 Opening Stock from API:', item.opening_stock)
    console.log('📊 Current Stock from API:', item.current_stock)
    
    setEditingItem(item)
    setFormData({
      item_type: item.item_type,
      name: item.name || '',
      category: item.category || '',
      unit: item.unit || (item.item_type === 'raw_material' ? 'KG' : 'PCS'),
      hsn_code: item.hsn_code || '',
      gst_rate: item.gst_rate || 18,
      purchase_rate: item.purchase_rate || 0,
      sales_rate: item.sales_rate || 0,
      mrp: item.mrp || 0,
      opening_stock: item.opening_stock !== undefined ? parseFloat(item.opening_stock) : 0,
      current_stock: item.current_stock !== undefined ? parseFloat(item.current_stock) : 0,
      min_stock: item.min_stock !== undefined ? parseFloat(item.min_stock) : 0,
      max_stock: item.max_stock !== undefined ? parseFloat(item.max_stock) : 0,
      location: item.location || ''
    })
    setShowModal(true)
  }

  const handleDelete = async (item) => {
    if (confirm(`Are you sure you want to delete this ${item.item_type === 'raw_material' ? 'raw material' : 'finished good'}?`)) {
      try {
        await axios.delete(`http://localhost:5000/api/items/${item.item_type}/${item.id}`)
        toast.success('Item deleted successfully')
        fetchItems()
      } catch (error) {
        toast.error('Delete failed')
      }
    }
  }

  const resetForm = () => {
    setEditingItem(null)
    setFormData({
      item_type: 'raw_material',
      name: '',
      category: '',
      unit: 'KG',
      hsn_code: '',
      gst_rate: 18,
      purchase_rate: 0,
      sales_rate: 0,
      mrp: 0,
      opening_stock: 0,
      current_stock: 0,
      min_stock: 0,
      max_stock: 0,
      location: ''
    })
  }

  const filteredItems = items.filter(item =>
    item.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.hsn_code?.includes(searchTerm) ||
    item.location?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 0
    }).format(amount)
  }

  const getStockStatus = (current, min) => {
    if (current <= 0) return 'text-red-400'
    if (current <= min) return 'text-yellow-400'
    return 'text-green-400'
  }

  const getTypeBadge = (type) => {
    return type === 'raw_material' 
      ? <span className="px-2 py-1 bg-blue-500/20 text-blue-400 rounded-full text-xs">Raw Material</span>
      : <span className="px-2 py-1 bg-green-500/20 text-green-400 rounded-full text-xs">Finished Good</span>
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-pink-900">
      {/* Background */}
      <div className="absolute inset-0 bg-black/30 backdrop-blur-[2px]" />
      
      {/* Content */}
      <div className="relative">
        {/* Header */}
        <header className="bg-white/10 backdrop-blur-xl border-b border-white/20">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <CubeIcon className="h-8 w-8 text-pink-400" />
                <h1 className="text-2xl font-bold text-white">
                  ITEM MASTER
                </h1>
              </div>
              <button
                onClick={() => router.push('/dashboard')}
                className="px-4 py-2 bg-white/10 border border-white/20 
                  rounded-lg text-white hover:bg-white/20
                  transition-all duration-200"
              >
                ← Back to Dashboard
              </button>
            </div>
          </div>
        </header>

        {/* Main Content */}
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {/* Actions Bar */}
          <div className="flex flex-col sm:flex-row gap-4 justify-between mb-6">
            {/* Search */}
            <div className="relative flex-1 max-w-md">
              <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-white/50" />
              <input
                type="text"
                placeholder="Search items by name, code, HSN..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white/10 border border-white/20 
                  rounded-lg text-white placeholder-white/50
                  focus:outline-none focus:ring-2 focus:ring-pink-500"
              />
            </div>
            
            {/* Filter Tabs */}
            <div className="flex gap-2">
              <button
                onClick={() => setFilterType('all')}
                className={`px-4 py-2 rounded-lg transition-all duration-200 ${
                  filterType === 'all' 
                    ? 'bg-pink-500 text-white' 
                    : 'bg-white/10 text-white/70 hover:bg-white/20'
                }`}
              >
                All Items
              </button>
              <button
                onClick={() => setFilterType('raw_material')}
                className={`px-4 py-2 rounded-lg transition-all duration-200 ${
                  filterType === 'raw_material' 
                    ? 'bg-blue-500 text-white' 
                    : 'bg-white/10 text-white/70 hover:bg-white/20'
                }`}
              >
                Raw Materials
              </button>
              <button
                onClick={() => setFilterType('finished_good')}
                className={`px-4 py-2 rounded-lg transition-all duration-200 ${
                  filterType === 'finished_good' 
                    ? 'bg-green-500 text-white' 
                    : 'bg-white/10 text-white/70 hover:bg-white/20'
                }`}
              >
                Finished Goods
              </button>
            </div>
            
            {/* Add Button */}
            <button
              onClick={() => {
                resetForm()
                setShowModal(true)
              }}
              className="px-4 py-2 bg-gradient-to-r from-green-500 to-emerald-600
                text-white rounded-lg hover:from-green-600 hover:to-emerald-700
                flex items-center justify-center gap-2"
            >
              <PlusIcon className="h-5 w-5" />
              Add Item
            </button>
          </div>

          {/* Items Table */}
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-white/5">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Type</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Code</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Item Name</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Unit</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">HSN</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">GST</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Rate</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Opening Stock</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Location</th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-white/60 uppercase">Actions</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-white/10">
                  {filteredItems.map((item) => (
                    <tr key={`${item.item_type}-${item.id}`} className="hover:bg-white/5 transition-colors">
                      <td className="px-6 py-4 text-sm">
                        {getTypeBadge(item.item_type)}
                       </td>
                      <td className="px-6 py-4 text-sm text-white font-mono">{item.code}</td>
                      <td className="px-6 py-4 text-sm text-white font-medium">{item.name}</td>
                      <td className="px-6 py-4 text-sm text-white/70">{item.unit}</td>
                      <td className="px-6 py-4 text-sm text-white/70">{item.hsn_code}</td>
                      <td className="px-6 py-4 text-sm text-white/70">{item.gst_rate}%</td>
                      <td className="px-6 py-4 text-sm text-green-400">
                        {item.item_type === 'raw_material' 
                          ? formatCurrency(item.purchase_rate)
                          : formatCurrency(item.sales_rate)}
                      </td>
                      <td className="px-6 py-4 text-sm font-semibold">
                        {item.opening_stock} {item.unit}
                      </td>
                      <td className="px-6 py-4 text-sm text-white/70">{item.location}</td>
                      <td className="px-6 py-4 text-sm">
                        <button
                          onClick={() => handleEdit(item)}
                          className="text-blue-400 hover:text-blue-300 mr-3 transition-colors"
                          title="Edit Item"
                        >
                          <PencilIcon className="h-5 w-5 inline" />
                        </button>
                        <button
                          onClick={() => handleDelete(item)}
                          className="text-red-400 hover:text-red-300 transition-colors"
                          title="Delete Item"
                        >
                          <TrashIcon className="h-5 w-5 inline" />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            
            {/* Empty State */}
            {filteredItems.length === 0 && (
              <div className="text-center py-16">
                <CubeIcon className="h-16 w-16 text-white/20 mx-auto mb-4" />
                <p className="text-white/50 text-lg">No items found</p>
                <p className="text-white/30 text-sm mt-2">Click "Add Item" to create your first item</p>
              </div>
            )}
          </div>

          {/* Summary Cards */}
          {items.length > 0 && (
            <div className="mt-6 grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="bg-blue-500/20 backdrop-blur-xl border border-blue-500/30 rounded-xl p-4">
                <div className="flex justify-between items-center">
                  <span className="text-blue-300">Raw Materials:</span>
                  <span className="text-white font-semibold">
                    {items.filter(i => i.item_type === 'raw_material').length}
                  </span>
                </div>
              </div>
              <div className="bg-green-500/20 backdrop-blur-xl border border-green-500/30 rounded-xl p-4">
                <div className="flex justify-between items-center">
                  <span className="text-green-300">Finished Goods:</span>
                  <span className="text-white font-semibold">
                    {items.filter(i => i.item_type === 'finished_good').length}
                  </span>
                </div>
              </div>
              <div className="bg-purple-500/20 backdrop-blur-xl border border-purple-500/30 rounded-xl p-4">
                <div className="flex justify-between items-center">
                  <span className="text-purple-300">Total Items:</span>
                  <span className="text-white font-semibold">{items.length}</span>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Item Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6 w-full max-w-2xl max-h-[90vh] overflow-y-auto">
            <div className="flex items-center gap-3 mb-4">
              {formData.item_type === 'raw_material' ? (
                <BeakerIcon className="h-6 w-6 text-blue-400" />
              ) : (
                <CubeIcon className="h-6 w-6 text-green-400" />
              )}
              <h2 className="text-xl font-semibold text-white">
                {editingItem ? 'Edit Item' : 'Add New Item'}
              </h2>
            </div>
            
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {/* Item Type Selection */}
                <div className="col-span-2">
                  <label className="block text-white/80 text-sm mb-1">Item Type *</label>
                  <div className="relative">
                    <select
                      name="item_type"
                      value={formData.item_type}
                      onChange={handleTypeChange}
                      className="w-full px-3 py-2 bg-white/10 border border-white/20 
                        rounded-lg text-white appearance-none
                        focus:outline-none focus:ring-2 focus:ring-pink-500"
                      required
                    >
                      <option value="raw_material">Raw Material</option>
                      <option value="finished_good">Finished Good</option>
                    </select>
                    <ChevronDownIcon className="absolute right-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-white/50" />
                  </div>
                </div>

                {/* Basic Information */}
                <div className="col-span-2">
                  <h3 className="text-white/80 text-sm font-semibold mb-2">Basic Information</h3>
                </div>
                
                {/* Item Name */}
                <div className="col-span-2">
                  <label className="block text-white/80 text-sm mb-1">Item Name *</label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    required
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white placeholder-white/50
                      focus:outline-none focus:ring-2 focus:ring-pink-500"
                    placeholder={formData.item_type === 'raw_material' 
                      ? "e.g., Plastic Granules - HDPE" 
                      : "e.g., Plastic Chair - Premium"}
                  />
                </div>
                
                {/* Unit */}
                <div>
                  <label className="block text-white/80 text-sm mb-1">Unit *</label>
                  <select
                    name="unit"
                    value={formData.unit}
                    onChange={handleInputChange}
                    required
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-pink-500"
                  >
                    <option value="KG">Kilogram (KG)</option>
                    <option value="PCS">Pieces (PCS)</option>
                    <option value="MTR">Meter (MTR)</option>
                    <option value="LTR">Liter (LTR)</option>
                    <option value="BOX">Box</option>
                  </select>
                </div>
                
                {/* HSN Code */}
                <div>
                  <label className="block text-white/80 text-sm mb-1">HSN Code</label>
                  <input
                    type="text"
                    name="hsn_code"
                    value={formData.hsn_code}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white placeholder-white/50
                      focus:outline-none focus:ring-2 focus:ring-pink-500"
                    placeholder="e.g., 39269099"
                  />
                </div>
                
                {/* GST Rate */}
                <div>
                  <label className="block text-white/80 text-sm mb-1">GST Rate (%)</label>
                  <select
                    name="gst_rate"
                    value={formData.gst_rate}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-pink-500"
                  >
                    <option value="0">0%</option>
                    <option value="5">5%</option>
                    <option value="12">12%</option>
                    <option value="18">18%</option>
                    <option value="28">28%</option>
                  </select>
                </div>
                
                {/* Conditional Fields based on Item Type */}
                {formData.item_type === 'raw_material' ? (
                  // Raw Material Fields
                  <div>
                    <label className="block text-white/80 text-sm mb-1">Purchase Rate (₹)</label>
                    <input
                      type="number"
                      name="purchase_rate"
                      value={formData.purchase_rate}
                      onChange={handleInputChange}
                      min="0"
                      step="any"
                      className="w-full px-3 py-2 bg-white/10 border border-white/20 
                        rounded-lg text-white placeholder-white/50
                        focus:outline-none focus:ring-2 focus:ring-pink-500"
                      placeholder="0"
                    />
                  </div>
                ) : (
                  // Finished Good Fields
                  <>
                    <div>
                      <label className="block text-white/80 text-sm mb-1">Sales Rate (₹)</label>
                      <input
                        type="number"
                        name="sales_rate"
                        value={formData.sales_rate}
                        onChange={handleInputChange}
                        min="0"
                        step="any"
                        className="w-full px-3 py-2 bg-white/10 border border-white/20 
                          rounded-lg text-white placeholder-white/50
                          focus:outline-none focus:ring-2 focus:ring-pink-500"
                        placeholder="0"
                      />
                    </div>
                    <div>
                      <label className="block text-white/80 text-sm mb-1">MRP (₹)</label>
                      <input
                        type="number"
                        name="mrp"
                        value={formData.mrp}
                        onChange={handleInputChange}
                        min="0"
                        step="any"
                        className="w-full px-3 py-2 bg-white/10 border border-white/20 
                          rounded-lg text-white placeholder-white/50
                          focus:outline-none focus:ring-2 focus:ring-pink-500"
                        placeholder="0"
                      />
                    </div>
                  </>
                )}
                
                {/* Stock Information */}
                <div className="col-span-2 mt-4">
                  <h3 className="text-white/80 text-sm font-semibold mb-2">Stock Information</h3>
                </div>
                
                <div>
                  <label className="block text-white/80 text-sm mb-1">Opening Stock</label>
                  <input
                    type="number"
                    name="opening_stock"
                    value={formData.opening_stock}
                    onChange={handleInputChange}
                    min="0"
                    step="any"
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white placeholder-white/50
                      focus:outline-none focus:ring-2 focus:ring-pink-500"
                    placeholder="0"
                  />
                  <p className="text-white/50 text-xs mt-1">Base stock quantity (editable)</p>
                </div>
                
                <div>
                  <label className="block text-white/80 text-sm mb-1">Current Stock</label>
                  <input
                    type="number"
                    name="current_stock"
                    value={formData.current_stock}
                    disabled
                    className="w-full px-3 py-2 bg-white/5 border border-white/10 
                      rounded-lg text-white/70 cursor-not-allowed"
                    placeholder="0"
                  />
                  <p className="text-yellow-400/70 text-xs mt-1">⚠️ Auto-calculated from transactions. Read-only.</p>
                </div>
                
                <div>
                  <label className="block text-white/80 text-sm mb-1">Min Stock Level</label>
                  <input
                    type="number"
                    name="min_stock"
                    value={formData.min_stock}
                    onChange={handleInputChange}
                    min="0"
                    step="any"
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white placeholder-white/50
                      focus:outline-none focus:ring-2 focus:ring-pink-500"
                    placeholder="0"
                  />
                </div>
                
                <div>
                  <label className="block text-white/80 text-sm mb-1">Max Stock Level</label>
                  <input
                    type="number"
                    name="max_stock"
                    value={formData.max_stock}
                    onChange={handleInputChange}
                    min="0"
                    step="any"
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white placeholder-white/50
                      focus:outline-none focus:ring-2 focus:ring-pink-500"
                    placeholder="0"
                  />
                </div>
                
                {/* Location */}
                <div className="col-span-2">
                  <label className="block text-white/80 text-sm mb-1">Storage Location</label>
                  <input
                    type="text"
                    name="location"
                    value={formData.location}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 
                      rounded-lg text-white placeholder-white/50
                      focus:outline-none focus:ring-2 focus:ring-pink-500"
                    placeholder="e.g., Warehouse A, Rack 1"
                  />
                </div>
              </div>
              
              {/* Form Actions */}
              <div className="flex justify-end space-x-3 mt-6 pt-4 border-t border-white/10">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="px-4 py-2 bg-white/10 border border-white/20 
                    rounded-lg text-white hover:bg-white/20
                    transition-all duration-200"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-gradient-to-r from-pink-500 to-purple-600
                    text-white rounded-lg hover:from-pink-600 hover:to-purple-700
                    transition-all duration-200 font-medium"
                >
                  {editingItem ? 'Update Item' : 'Save Item'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import axios from 'axios'
import Link from 'next/link'
import toast from 'react-hot-toast'
import { 
  ArrowLeftIcon,
  CalendarIcon,
  ClockIcon,
  CheckCircleIcon,
  XCircleIcon,
  UserIcon,
  MagnifyingGlassIcon,
  ArrowPathIcon,
  DocumentTextIcon,
  PrinterIcon,
  ChartBarIcon
} from '@heroicons/react/24/outline'

export default function AttendancePage() {
  const router = useRouter()
  const [loading, setLoading] = useState(true)
  const [employees, setEmployees] = useState([])
  const [attendance, setAttendance] = useState([])
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0])
  const [searchTerm, setSearchTerm] = useState('')
  const [stats, setStats] = useState({
    present: 0,
    absent: 0,
    late: 0,
    halfDay: 0,
    leave: 0,
    total: 0
  })

  useEffect(() => {
    checkAuth()
    fetchEmployees()
    fetchAttendance()
  }, [])

  useEffect(() => {
    if (selectedDate) {
      fetchAttendance()
    }
  }, [selectedDate])

  const checkAuth = () => {
    const user = localStorage.getItem('user')
    if (!user) {
      router.push('/')
    }
  }

  const fetchEmployees = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/employees')
      const employeeData = response.data.employees || response.data || []
      setEmployees(employeeData.filter(e => e.status === 'active'))
    } catch (error) {
      console.error('Error fetching employees:', error)
      toast.error('Failed to fetch employees')
    }
  }

  const fetchAttendance = async () => {
    try {
      setLoading(true)
      const response = await axios.get(`http://localhost:5000/api/attendance?date=${selectedDate}`)
      const attendanceData = response.data.attendance || response.data || []
      setAttendance(attendanceData)
      
      // Calculate stats
      setStats({
        present: attendanceData.filter(a => a.status === 'present').length,
        absent: attendanceData.filter(a => a.status === 'absent').length,
        late: attendanceData.filter(a => a.status === 'late').length,
        halfDay: attendanceData.filter(a => a.status === 'halfday').length,
        leave: attendanceData.filter(a => a.status === 'leave').length,
        total: attendanceData.length
      })
    } catch (error) {
      console.error('Error fetching attendance:', error)
      toast.error('Failed to fetch attendance')
    } finally {
      setLoading(false)
    }
  }

  const markAttendance = async (employeeId, status, checkIn = null, checkOut = null) => {
    try {
      const data = {
        employee_id: employeeId,
        date: selectedDate,
        status,
        check_in: checkIn,
        check_out: checkOut
      }
      
      await axios.post('http://localhost:5000/api/attendance', data)
      toast.success('Attendance marked successfully')
      fetchAttendance()
    } catch (error) {
      console.error('Error marking attendance:', error)
      toast.error('Failed to mark attendance')
    }
  }

  const updateAttendance = async (attendanceId, data) => {
    try {
      await axios.put(`http://localhost:5000/api/attendance/${attendanceId}`, data)
      toast.success('Attendance updated')
      fetchAttendance()
    } catch (error) {
      console.error('Error updating attendance:', error)
      toast.error('Failed to update attendance')
    }
  }

  const getEmployeeAttendance = (employeeId) => {
    return attendance.find(a => a.employee_id === employeeId)
  }

  const filteredEmployees = employees.filter(emp => 
    emp.first_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.last_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.employee_code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.department?.toLowerCase().includes(searchTerm.toLowerCase())
  )

  const getStatusColor = (status) => {
    switch(status) {
      case 'present': return 'bg-green-500/20 text-green-400 border-green-500/30'
      case 'absent': return 'bg-red-500/20 text-red-400 border-red-500/30'
      case 'late': return 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'
      case 'halfday': return 'bg-orange-500/20 text-orange-400 border-orange-500/30'
      case 'leave': return 'bg-blue-500/20 text-blue-400 border-blue-500/30'
      default: return 'bg-gray-500/20 text-gray-400 border-gray-500/30'
    }
  }

  const handleBulkMark = (status) => {
    filteredEmployees.forEach(emp => {
      const existing = getEmployeeAttendance(emp.id)
      if (!existing) {
        markAttendance(emp.id, status)
      }
    })
  }

  const handlePrint = () => {
    const printWindow = window.open('', '_blank')
    if (printWindow) {
      printWindow.document.write(`
        <html>
          <head>
            <title>Attendance Report - ${selectedDate}</title>
            <style>
              body { font-family: Arial, sans-serif; margin: 20px; }
              h1 { color: #333; text-align: center; }
              h2 { color: #666; }
              table { width: 100%; border-collapse: collapse; margin-top: 20px; }
              th { background: #f0f0f0; padding: 8px; text-align: left; }
              td { padding: 8px; border-bottom: 1px solid #ddd; }
              .header { display: flex; justify-content: space-between; margin-bottom: 20px; }
              .stats { display: grid; grid-template-columns: repeat(6, 1fr); gap: 10px; margin: 20px 0; }
              .stat-card { background: #f9f9f9; padding: 10px; border-radius: 5px; text-align: center; }
              .present { color: green; }
              .absent { color: red; }
              .late { color: orange; }
              .footer { margin-top: 30px; text-align: center; color: #999; }
            </style>
          </head>
          <body>
            <div class="header">
              <h2>FOUR (R) PLASTIC</h2>
              <div>
                <p>Date: ${new Date(selectedDate).toLocaleDateString('en-IN')}</p>
                <p>Generated: ${new Date().toLocaleString()}</p>
              </div>
            </div>
            
            <h1>Daily Attendance Report</h1>
            
            <div class="stats">
              <div class="stat-card"><strong>Present</strong><br>${stats.present}</div>
              <div class="stat-card"><strong>Absent</strong><br>${stats.absent}</div>
              <div class="stat-card"><strong>Late</strong><br>${stats.late}</div>
              <div class="stat-card"><strong>Half Day</strong><br>${stats.halfDay}</div>
              <div class="stat-card"><strong>Leave</strong><br>${stats.leave}</div>
              <div class="stat-card"><strong>Total</strong><br>${stats.total}</div>
            </div>
            
            <table>
              <thead>
                <tr>
                  <th>Emp Code</th>
                  <th>Employee Name</th>
                  <th>Department</th>
                  <th>Check In</th>
                  <th>Check Out</th>
                  <th>Hours</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                ${filteredEmployees.map(emp => {
                  const att = getEmployeeAttendance(emp.id)
                  return `
                    <tr>
                      <td>${emp.employee_code}</td>
                      <td>${emp.first_name} ${emp.last_name}</td>
                      <td>${emp.department || '-'}</td>
                      <td>${att?.check_in || '-'}</td>
                      <td>${att?.check_out || '-'}</td>
                      <td>${att?.hours || '-'}</td>
                      <td class="${att?.status || 'absent'}">${att?.status || 'Absent'}</td>
                    </tr>
                  `
                }).join('')}
              </tbody>
            </table>
            
            <div class="footer">
              <p>This is a computer generated report</p>
            </div>
          </body>
        </html>
      `)
      printWindow.document.close()
      printWindow.print()
    }
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-pink-900 flex items-center justify-center">
        <div className="text-center">
          <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-white border-r-transparent"></div>
          <p className="text-white/70 mt-4">Loading attendance...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-pink-900">
      <div className="absolute inset-0 bg-black/30 backdrop-blur-[2px]" />
      
      <div className="relative">
        {/* Header */}
        <header className="bg-white/10 backdrop-blur-xl border-b border-white/20 sticky top-0 z-10">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <button
                  onClick={() => router.push('/payroll')}
                  className="p-2 bg-white/10 border border-white/20 rounded-lg text-white hover:bg-white/20"
                >
                  <ArrowLeftIcon className="h-5 w-5" />
                </button>
                <CalendarIcon className="h-8 w-8 text-pink-400" />
                <h1 className="text-2xl font-bold text-white">Daily Attendance</h1>
              </div>
              <div className="flex items-center gap-3">
                <button
                  onClick={fetchAttendance}
                  className="p-2 bg-white/10 border border-white/20 rounded-lg text-white hover:bg-white/20"
                  title="Refresh"
                >
                  <ArrowPathIcon className="h-5 w-5" />
                </button>
                <Link
                  href="/payroll/attendance/report"
                  className="flex items-center gap-2 px-4 py-2 bg-white/10 border border-white/20 
                    text-white rounded-lg hover:bg-white/20"
                >
                  <ChartBarIcon className="h-5 w-5" />
                  Reports
                </Link>
                <button
                  onClick={handlePrint}
                  className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-pink-500 to-purple-600 
                    text-white rounded-lg hover:from-pink-600 hover:to-purple-700"
                >
                  <PrinterIcon className="h-5 w-5" />
                  Print
                </button>
              </div>
            </div>
          </div>
        </header>

        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {/* Date Selection and Stats */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
            {/* Date Picker */}
            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
              <label className="block text-white/70 text-sm mb-2">Select Date</label>
              <input
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="w-full px-4 py-3 bg-gray-800 border border-white/20 rounded-lg text-white 
                  text-lg focus:outline-none focus:ring-2 focus:ring-pink-500"
                style={{ backgroundColor: '#1f2937' }}
              />
            </div>

            {/* Quick Stats */}
            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
              <h3 className="text-white/70 text-sm mb-3">Today's Summary</h3>
              <div className="grid grid-cols-3 gap-3">
                <div className="text-center">
                  <p className="text-green-400 text-2xl font-bold">{stats.present}</p>
                  <p className="text-white/50 text-xs">Present</p>
                </div>
                <div className="text-center">
                  <p className="text-red-400 text-2xl font-bold">{stats.absent}</p>
                  <p className="text-white/50 text-xs">Absent</p>
                </div>
                <div className="text-center">
                  <p className="text-yellow-400 text-2xl font-bold">{stats.late}</p>
                  <p className="text-white/50 text-xs">Late</p>
                </div>
                <div className="text-center">
                  <p className="text-orange-400 text-2xl font-bold">{stats.halfDay}</p>
                  <p className="text-white/50 text-xs">Half Day</p>
                </div>
                <div className="text-center">
                  <p className="text-blue-400 text-2xl font-bold">{stats.leave}</p>
                  <p className="text-white/50 text-xs">Leave</p>
                </div>
                <div className="text-center">
                  <p className="text-white text-2xl font-bold">{stats.total}</p>
                  <p className="text-white/50 text-xs">Total</p>
                </div>
              </div>
            </div>
          </div>

          {/* Bulk Actions */}
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-4 mb-6">
            <div className="flex items-center justify-between">
              <h3 className="text-white font-semibold">Bulk Actions</h3>
              <div className="flex gap-2">
                <button
                  onClick={() => handleBulkMark('present')}
                  className="px-3 py-1.5 bg-green-500/20 border border-green-500/30 text-green-400 rounded-lg text-sm hover:bg-green-500/30"
                >
                  Mark All Present
                </button>
                <button
                  onClick={() => handleBulkMark('absent')}
                  className="px-3 py-1.5 bg-red-500/20 border border-red-500/30 text-red-400 rounded-lg text-sm hover:bg-red-500/30"
                >
                  Mark All Absent
                </button>
              </div>
            </div>
          </div>

          {/* Search */}
          <div className="mb-4">
            <div className="relative">
              <MagnifyingGlassIcon className="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-white/50" />
              <input
                type="text"
                placeholder="Search employees by name, code, department..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white/10 border border-white/20 
                  rounded-lg text-white placeholder-white/50
                  focus:outline-none focus:ring-2 focus:ring-pink-500"
              />
            </div>
          </div>

          {/* Results Info */}
          <div className="mb-3 text-white/60 text-sm">
            Showing {filteredEmployees.length} employees
          </div>

          {/* Attendance Table */}
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-white/5">
                  <tr>
                    <th className="px-4 py-3 text-left text-white/60 text-sm">Emp Code</th>
                    <th className="px-4 py-3 text-left text-white/60 text-sm">Employee</th>
                    <th className="px-4 py-3 text-left text-white/60 text-sm">Department</th>
                    <th className="px-4 py-3 text-left text-white/60 text-sm">Check In</th>
                    <th className="px-4 py-3 text-left text-white/60 text-sm">Check Out</th>
                    <th className="px-4 py-3 text-left text-white/60 text-sm">Hours</th>
                    <th className="px-4 py-3 text-left text-white/60 text-sm">Status</th>
                    <th className="px-4 py-3 text-right text-white/60 text-sm">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/10">
                  {filteredEmployees.map((employee) => {
                    const att = getEmployeeAttendance(employee.id)
                    return (
                      <tr key={employee.id} className="hover:bg-white/5">
                        <td className="px-4 py-3 text-white font-mono text-sm">
                          {employee.employee_code}
                        </td>
                        <td className="px-4 py-3">
                          <div className="flex items-center gap-2">
                            <div className="w-8 h-8 rounded-full bg-pink-500/20 flex items-center justify-center">
                              <span className="text-pink-400 text-sm font-semibold">
                                {employee.first_name?.[0]}{employee.last_name?.[0]}
                              </span>
                            </div>
                            <div>
                              <p className="text-white font-medium">
                                {employee.first_name} {employee.last_name}
                              </p>
                            </div>
                          </div>
                        </td>
                        <td className="px-4 py-3 text-white/70 text-sm">
                          {employee.department || '-'}
                        </td>
                        <td className="px-4 py-3">
                          <input
                            type="time"
                            value={att?.check_in || ''}
                            onChange={(e) => {
                              if (att) {
                                updateAttendance(att.id, { ...att, check_in: e.target.value })
                              } else {
                                markAttendance(employee.id, 'present', e.target.value, null)
                              }
                            }}
                            className="w-24 px-2 py-1 bg-gray-800 border border-white/20 rounded text-white text-sm
                              focus:outline-none focus:ring-1 focus:ring-pink-500"
                            style={{ backgroundColor: '#1f2937' }}
                          />
                        </td>
                        <td className="px-4 py-3">
                          <input
                            type="time"
                            value={att?.check_out || ''}
                            onChange={(e) => {
                              if (att) {
                                updateAttendance(att.id, { ...att, check_out: e.target.value })
                              }
                            }}
                            disabled={!att}
                            className="w-24 px-2 py-1 bg-gray-800 border border-white/20 rounded text-white text-sm
                              focus:outline-none focus:ring-1 focus:ring-pink-500 disabled:opacity-50"
                            style={{ backgroundColor: '#1f2937' }}
                          />
                        </td>
                        <td className="px-4 py-3 text-white text-sm">
                          {att?.hours || '-'}
                        </td>
                        <td className="px-4 py-3">
                          <select
                            value={att?.status || 'absent'}
                            onChange={(e) => {
                              if (att) {
                                updateAttendance(att.id, { ...att, status: e.target.value })
                              } else {
                                markAttendance(employee.id, e.target.value)
                              }
                            }}
                            className={`px-2 py-1 rounded border text-sm ${getStatusColor(att?.status || 'absent')}`}
                            style={{ backgroundColor: '#1f2937' }}
                          >
                            <option value="present">Present</option>
                            <option value="absent">Absent</option>
                            <option value="late">Late</option>
                            <option value="halfday">Half Day</option>
                            <option value="leave">Leave</option>
                          </select>
                        </td>
                        <td className="px-4 py-3 text-right">
                          {att && (
                            <button
                              onClick={() => {
                                if (confirm('Delete this attendance record?')) {
                                  axios.delete(`http://localhost:5000/api/attendance/${att.id}`)
                                    .then(() => {
                                      toast.success('Attendance deleted')
                                      fetchAttendance()
                                    })
                                    .catch(() => toast.error('Failed to delete'))
                                }
                              }}
                              className="p-1 text-red-400 hover:bg-red-500/20 rounded"
                            >
                              <XCircleIcon className="h-4 w-4" />
                            </button>
                          )}
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>

            {filteredEmployees.length === 0 && (
              <div className="text-center py-12">
                <UserIcon className="h-12 w-12 mx-auto mb-3 text-white/20" />
                <p className="text-white/50">No active employees found</p>
              </div>
            )}
          </div>
        </main>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import axios from 'axios'
import Link from 'next/link'
import toast from 'react-hot-toast'
import { 
  ArrowLeftIcon,
  UserIcon,
  EnvelopeIcon,
  PhoneIcon,
  CalendarIcon,
  BanknotesIcon,
  BriefcaseIcon,
  IdentificationIcon,
  MapPinIcon,
  ExclamationTriangleIcon,
  UserGroupIcon,
  HeartIcon
} from '@heroicons/react/24/outline'

export default function NewEmployee() {
  const router = useRouter()
  const [loading, setLoading] = useState(false)
  const [generatingCode, setGeneratingCode] = useState(true)
  const [apiError, setApiError] = useState('')
  const [existingEmails, setExistingEmails] = useState([])
  const [emailError, setEmailError] = useState('')
  
  const [formData, setFormData] = useState({
    employee_code: '',
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
    alternate_phone: '',
    gender: '', // Male, Female, Other
    marital_status: 'single', // single, married, divorced, widowed
    date_of_birth: '',
    blood_group: '', // A+, A-, B+, B-, O+, O-, AB+, AB-
    department: '',
    designation: '',
    join_date: new Date().toISOString().split('T')[0],
    basic_salary: '',
    hra: '',
    conveyance: '',
    medical: '',
    special_allowance: '',
    pf_number: '',
    esi_number: '',
    pan_number: '',
    aadhar_number: '',
    bank_name: '',
    bank_account: '',
    ifsc_code: '',
    address: '',
    city: '',
    state: '',
    pincode: '',
    emergency_contact_name: '',
    emergency_contact_phone: '',
    emergency_contact_relation: '',
    status: 'active'
  })

  useEffect(() => {
    // Check authentication
    const user = localStorage.getItem('user')
    if (!user) {
      router.push('/')
      return
    }
    
    // Generate employee code only once
    generateEmployeeCode()
    fetchExistingEmails()
  }, [])

  const generateEmployeeCode = async () => {
    try {
      setGeneratingCode(true)
      setApiError('')
      
      console.log('Fetching last employee code...')
      const response = await axios.get('http://localhost:5000/api/employees/last-code')
      console.log('Last code response:', response.data)
      
      const lastCode = response.data.lastCode || 'EMP000'
      const num = parseInt(lastCode.replace('EMP', '')) + 1
      const newCode = `EMP${num.toString().padStart(3, '0')}`
      setFormData(prev => ({ ...prev, employee_code: newCode }))
      
    } catch (error) {
      console.error('Error generating code:', error)
      // Fallback code using timestamp
      const fallbackCode = `EMP${Date.now().toString().slice(-5)}`
      setFormData(prev => ({ ...prev, employee_code: fallbackCode }))
      setApiError('Could not generate employee code automatically')
    } finally {
      setGeneratingCode(false)
    }
  }

  const fetchExistingEmails = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/employees')
      let employees = []
      if (response.data && response.data.employees) {
        employees = response.data.employees
      } else if (Array.isArray(response.data)) {
        employees = response.data
      }
      const emails = employees.map(emp => emp.email).filter(Boolean)
      setExistingEmails(emails)
    } catch (error) {
      console.error('Error fetching employees:', error)
    }
  }

  const handleInputChange = (e) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    
    // Clear email error when typing
    if (name === 'email') {
      setEmailError('')
    }
  }

  const checkEmailAvailability = (email) => {
    if (!email) return true
    if (existingEmails.includes(email)) {
      setEmailError('This email is already registered. Please use a different email.')
      return false
    }
    return true
  }

  const suggestEmail = () => {
    const firstName = formData.first_name?.toLowerCase().replace(/\s+/g, '') || 'user'
    const lastName = formData.last_name?.toLowerCase().replace(/\s+/g, '') || ''
    const randomNum = Math.floor(Math.random() * 1000)
    
    const suggestions = [
      `${firstName}.${lastName}@company.com`,
      `${firstName}${lastName}@gmail.com`,
      `${firstName}.${lastName}${randomNum}@email.com`,
      `${firstName}${randomNum}@work.com`
    ]
    
    // Find first unused email
    for (const suggestion of suggestions) {
      if (!existingEmails.includes(suggestion)) {
        return suggestion
      }
    }
    return `${firstName}${lastName}${Date.now()}@email.com`
  }

  const handleSuggestEmail = () => {
    const suggested = suggestEmail()
    setFormData(prev => ({ ...prev, email: suggested }))
    setEmailError('')
  }

  const calculateTotalSalary = () => {
    const basic = parseFloat(formData.basic_salary) || 0
    const hra = parseFloat(formData.hra) || 0
    const conveyance = parseFloat(formData.conveyance) || 0
    const medical = parseFloat(formData.medical) || 0
    const special = parseFloat(formData.special_allowance) || 0
    return basic + hra + conveyance + medical + special
  }

  const validateForm = () => {
    const errors = []
    
    if (!formData.first_name?.trim()) errors.push('First name is required')
    if (!formData.last_name?.trim()) errors.push('Last name is required')
    if (!formData.email?.trim()) errors.push('Email is required')
    if (!formData.phone?.trim()) errors.push('Phone number is required')
    
    // Check if email exists
    if (existingEmails.includes(formData.email)) {
      errors.push('This email is already registered')
      setEmailError('This email is already registered')
    }
    
    const salary = parseFloat(formData.basic_salary)
    if (!formData.basic_salary || isNaN(salary) || salary <= 0) {
      errors.push('Valid basic salary is required')
    }
    
    return errors
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    // Validate form
    const errors = validateForm()
    if (errors.length > 0) {
      errors.forEach(error => toast.error(error))
      return
    }

    // Final email check
    if (!checkEmailAvailability(formData.email)) {
      toast.error('Please use a different email address')
      return
    }

    try {
      setLoading(true)
      setApiError('')
      
      // Prepare data - remove any empty strings to avoid validation issues
      const submitData = {}
      Object.keys(formData).forEach(key => {
        if (formData[key] !== '' && formData[key] !== null && formData[key] !== undefined) {
          submitData[key] = formData[key]
        }
      })
      
      // Ensure required fields are present
      submitData.first_name = formData.first_name
      submitData.last_name = formData.last_name
      submitData.email = formData.email
      submitData.phone = formData.phone
      submitData.basic_salary = parseFloat(formData.basic_salary)
      submitData.status = formData.status || 'active'
      
      console.log('Submitting employee data:', submitData)
      
      const response = await axios.post('http://localhost:5000/api/employees', submitData)
      
      console.log('Success response:', response.data)
      toast.success('Employee added successfully')
      router.push('/payroll/employees')
      
    } catch (error) {
      console.error('Error adding employee:', error)
      
      let errorMessage = 'Failed to add employee'
      
      if (error.response) {
        console.error('Error status:', error.response.status)
        console.error('Error data:', error.response.data)
        
        errorMessage = error.response.data?.message || 
                      error.response.data?.error || 
                      `Server error: ${error.response.status}`
        
        // Special handling for email error
        if (errorMessage.toLowerCase().includes('email')) {
          setEmailError('This email is already taken. Please use a different email.')
          fetchExistingEmails() // Refresh email list
        }
      } else if (error.request) {
        errorMessage = 'No response from server. Check if backend is running.'
      } else {
        errorMessage = error.message
      }
      
      setApiError(errorMessage)
      toast.error(errorMessage)
      
    } finally {
      setLoading(false)
    }
  }

  // Show loading while generating code
  if (generatingCode) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-pink-900 flex items-center justify-center">
        <div className="text-center">
          <div className="inline-block h-8 w-8 animate-spin rounded-full border-4 border-solid border-white border-r-transparent"></div>
          <p className="text-white/70 mt-4">Generating employee code...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-900 via-purple-900 to-pink-900">
      <div className="absolute inset-0 bg-black/30 backdrop-blur-[2px]" />
      
      <div className="relative">
        {/* Header */}
        <header className="bg-white/10 backdrop-blur-xl border-b border-white/20 sticky top-0 z-10">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
            <div className="flex items-center gap-4">
              <Link
                href="/payroll/employees"
                className="p-2 bg-white/10 border border-white/20 rounded-lg text-white hover:bg-white/20"
              >
                <ArrowLeftIcon className="h-5 w-5" />
              </Link>
              <UserIcon className="h-8 w-8 text-pink-400" />
              <h1 className="text-2xl font-bold text-white">Add New Employee</h1>
            </div>
          </div>
        </header>

        <main className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {/* Error Display */}
          {apiError && (
            <div className="mb-6 bg-red-500/10 border border-red-500/20 rounded-xl p-4">
              <div className="flex items-center gap-3">
                <ExclamationTriangleIcon className="h-5 w-5 text-red-400" />
                <p className="text-red-400 text-sm">{apiError}</p>
              </div>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Personal Information */}
            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
              <h2 className="text-white text-lg font-semibold mb-4 flex items-center gap-2">
                <UserIcon className="h-5 w-5 text-pink-400" />
                Personal Information
              </h2>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-white/70 text-sm mb-1">Employee Code</label>
                  <input
                    type="text"
                    name="employee_code"
                    value={formData.employee_code}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    readOnly
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">First Name *</label>
                  <input
                    type="text"
                    name="first_name"
                    value={formData.first_name}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    required
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Last Name *</label>
                  <input
                    type="text"
                    name="last_name"
                    value={formData.last_name}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    required
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Gender</label>
                  <select
                    name="gender"
                    value={formData.gender}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-gray-800 border border-white/20 rounded-lg text-white"
                    style={{ backgroundColor: '#1f2937' }}
                  >
                    <option value="">Select Gender</option>
                    <option value="male">Male</option>
                    <option value="female">Female</option>
                    <option value="other">Other</option>
                  </select>
                </div>

                <div>
                  <label className="block text-white/70 text-sm mb-1">Marital Status</label>
                  <select
                    name="marital_status"
                    value={formData.marital_status}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-gray-800 border border-white/20 rounded-lg text-white"
                    style={{ backgroundColor: '#1f2937' }}
                  >
                    <option value="single">Single</option>
                    <option value="married">Married</option>
                    <option value="divorced">Divorced</option>
                    <option value="widowed">Widowed</option>
                  </select>
                </div>

                <div>
                  <label className="block text-white/70 text-sm mb-1">Date of Birth</label>
                  <input
                    type="date"
                    name="date_of_birth"
                    value={formData.date_of_birth}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-gray-800 border border-white/20 rounded-lg text-white"
                    style={{ backgroundColor: '#1f2937' }}
                  />
                </div>

                <div>
                  <label className="block text-white/70 text-sm mb-1">Blood Group</label>
                  <select
                    name="blood_group"
                    value={formData.blood_group}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-gray-800 border border-white/20 rounded-lg text-white"
                    style={{ backgroundColor: '#1f2937' }}
                  >
                    <option value="">Select Blood Group</option>
                    <option value="A+">A+</option>
                    <option value="A-">A-</option>
                    <option value="B+">B+</option>
                    <option value="B-">B-</option>
                    <option value="O+">O+</option>
                    <option value="O-">O-</option>
                    <option value="AB+">AB+</option>
                    <option value="AB-">AB-</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Contact Information */}
            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
              <h2 className="text-white text-lg font-semibold mb-4 flex items-center gap-2">
                <EnvelopeIcon className="h-5 w-5 text-pink-400" />
                Contact Information
              </h2>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="md:col-span-2">
                  <label className="block text-white/70 text-sm mb-1">Email *</label>
                  <div className="flex gap-2">
                    <div className="flex-1">
                      <input
                        type="email"
                        name="email"
                        value={formData.email}
                        onChange={handleInputChange}
                        className={`w-full px-3 py-2 bg-white/10 border rounded-lg text-white ${
                          emailError ? 'border-red-500' : 'border-white/20'
                        }`}
                        placeholder="employee@company.com"
                        required
                      />
                      {emailError && (
                        <p className="text-red-400 text-xs mt-1">{emailError}</p>
                      )}
                    </div>
                    <button
                      type="button"
                      onClick={handleSuggestEmail}
                      className="px-3 py-2 bg-pink-500/20 border border-pink-500/30 text-pink-400 rounded-lg hover:bg-pink-500/30 text-sm whitespace-nowrap"
                    >
                      Suggest Email
                    </button>
                  </div>
                  <p className="text-white/50 text-xs mt-1">
                    Click "Suggest Email" to get a unique email suggestion
                  </p>
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Phone *</label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    placeholder="10-digit mobile number"
                    required
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Alternate Phone</label>
                  <input
                    type="tel"
                    name="alternate_phone"
                    value={formData.alternate_phone}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    placeholder="Optional"
                  />
                </div>
              </div>
            </div>

            {/* Employment Details */}
            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
              <h2 className="text-white text-lg font-semibold mb-4 flex items-center gap-2">
                <BriefcaseIcon className="h-5 w-5 text-pink-400" />
                Employment Details
              </h2>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-white/70 text-sm mb-1">Department</label>
                  <input
                    type="text"
                    name="department"
                    value={formData.department}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    placeholder="e.g., Production, Sales"
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Designation</label>
                  <input
                    type="text"
                    name="designation"
                    value={formData.designation}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    placeholder="e.g., Operator, Manager"
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Join Date</label>
                  <input
                    type="date"
                    name="join_date"
                    value={formData.join_date}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-gray-800 border border-white/20 rounded-lg text-white"
                    style={{ backgroundColor: '#1f2937' }}
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Status</label>
                  <select
                    name="status"
                    value={formData.status}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-gray-800 border border-white/20 rounded-lg text-white"
                    style={{ backgroundColor: '#1f2937' }}
                  >
                    <option value="active">Active</option>
                    <option value="inactive">Inactive</option>
                    <option value="onleave">On Leave</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Salary Details */}
            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
              <h2 className="text-white text-lg font-semibold mb-4 flex items-center gap-2">
                <BanknotesIcon className="h-5 w-5 text-pink-400" />
                Salary Details
              </h2>
              
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-white/70 text-sm mb-1">Basic Salary *</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-white/50">₹</span>
                    <input
                      type="number"
                      name="basic_salary"
                      value={formData.basic_salary}
                      onChange={handleInputChange}
                      step="any"
                      min="0"
                      className="w-full pl-8 pr-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                      required
                    />
                  </div>
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">HRA</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-white/50">₹</span>
                    <input
                      type="number"
                      name="hra"
                      value={formData.hra}
                      onChange={handleInputChange}
                      step="any"
                      min="0"
                      className="w-full pl-8 pr-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    />
                  </div>
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Conveyance</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-white/50">₹</span>
                    <input
                      type="number"
                      name="conveyance"
                      value={formData.conveyance}
                      onChange={handleInputChange}
                      step="any"
                      min="0"
                      className="w-full pl-8 pr-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    />
                  </div>
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Medical Allowance</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-white/50">₹</span>
                    <input
                      type="number"
                      name="medical"
                      value={formData.medical}
                      onChange={handleInputChange}
                      step="any"
                      min="0"
                      className="w-full pl-8 pr-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    />
                  </div>
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Special Allowance</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-white/50">₹</span>
                    <input
                      type="number"
                      name="special_allowance"
                      value={formData.special_allowance}
                      onChange={handleInputChange}
                      step="any"
                      min="0"
                      className="w-full pl-8 pr-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    />
                  </div>
                </div>
                
                <div className="bg-pink-500/10 rounded-lg p-3 flex items-center justify-between">
                  <span className="text-white/70 text-sm">Total Monthly</span>
                  <span className="text-white font-bold text-lg">
                    ₹{calculateTotalSalary().toLocaleString()}
                  </span>
                </div>
              </div>
            </div>

            {/* Emergency Contact */}
            <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-xl p-6">
              <h2 className="text-white text-lg font-semibold mb-4 flex items-center gap-2">
                <HeartIcon className="h-5 w-5 text-pink-400" />
                Emergency Contact
              </h2>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-white/70 text-sm mb-1">Contact Name</label>
                  <input
                    type="text"
                    name="emergency_contact_name"
                    value={formData.emergency_contact_name}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    placeholder="e.g., Spouse, Parent"
                  />
                </div>
                
                <div>
                  <label className="block text-white/70 text-sm mb-1">Contact Phone</label>
                  <input
                    type="tel"
                    name="emergency_contact_phone"
                    value={formData.emergency_contact_phone}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    placeholder="Emergency phone number"
                  />
                </div>

                <div>
                  <label className="block text-white/70 text-sm mb-1">Relation</label>
                  <input
                    type="text"
                    name="emergency_contact_relation"
                    value={formData.emergency_contact_relation}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 bg-white/10 border border-white/20 rounded-lg text-white"
                    placeholder="e.g., Father, Mother, Spouse"
                  />
                </div>
              </div>
            </div>

            {/* Form Actions */}
            <div className="flex justify-end gap-3">
              <Link
                href="/payroll/employees"
                className="px-4 py-2 bg-white/10 border border-white/20 text-white rounded-lg hover:bg-white/20"
              >
                Cancel
              </Link>
              <button
                type="submit"
                disabled={loading}
                className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-pink-500 to-purple-600 
                  text-white rounded-lg hover:from-pink-600 hover:to-purple-700 disabled:opacity-50"
              >
                {loading ? (
                  <>
                    <div className="h-4 w-4 animate-spin rounded-full border-2 border-solid border-white border-r-transparent"></div>
                    Saving...
                  </>
                ) : (
                  <>
                    <UserIcon className="h-5 w-5" />
                    Add Employee
                  </>
                )}
              </button>
            </div>
          </form>
        </main>
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import axios from 'axios'
import Link from 'next/link'
import toast from 'react-hot-toast'
import { 
  UsersIcon,
  CurrencyRupeeIcon,
  CalendarIcon,
  DocumentTextIcon,
  ChartBarIcon,
  ArrowPathIcon,
  UserGroupIcon,
  BanknotesIcon,
  ClockIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon
} from '@heroicons/react/24/outline'

export default function PayrollDashboard() {
  const router = useRouter()
  const [loading, setLoading] = useState(true)
  const [stats, setStats] = useState({
    totalEmployees: 0,
    activeEmployees: 0,
    totalAdvances: 0,
    pendingAdvances: 0,
    totalSurplus: 25000,
    totalPayouts: 450000,
    todayPresent: 0,
    todayAbsent: 0,
    monthlySalary: 850000
  })
  const [recentActivities, setRecentActivities] = useState([])
  const [upcomingPayouts, setUpcomingPayouts] = useState([])
  const [apiStatus, setApiStatus] = useState({
    employees: 'pending',
    advances: 'pending',
    attendance: 'pending'
  })

  useEffect(() => {
    checkAuth()
    fetchDashboardData()
  }, [])

  const checkAuth = () => {
    const user = localStorage.getItem('user')
    if (!user) {
      router.push('/')
    }
  }

  // Helper function to safely extract data from API responses
  const safeExtract = (response, key = null) => {
    if (!response) return []
    
    // If it's already an array
    if (Array.isArray(response)) return response
    
    // If it's an object
    if (typeof response === 'object') {
      // Check for specific key
      if (key && response[key] && Array.isArray(response[key])) {
        return response[key]
      }
      // Check for common patterns
      if (response.data && Array.isArray(response.data)) return response.data
      if (response.employees && Array.isArray(response.employees)) return response.employees
      if (response.advances && Array.isArray(response.advances)) return response.advances
      if (response.payouts && Array.isArray(response.payouts)) return response.payouts
      
      // If it's an object with numeric keys (like API returns object instead of array)
      if (Object.keys(response).length > 0 && !isNaN(Object.keys(response)[0])) {
        return Object.values(response)
      }
      
      // If it's a single object, wrap in array
      if (response.id || response.employee_code) {
        return [response]
      }
    }
    
    // If all else fails, return empty array
    console.warn('Could not extract array from response:', response)
    return []
  }

  const fetchDashboardData = async () => {
    try {
      setLoading(true)
      
      // Use Promise.allSettled to handle individual failures
      const [employeesRes, advancesRes, attendanceRes] = await Promise.allSettled([
        axios.get('http://localhost:5000/api/employees'),
        axios.get('http://localhost:5000/api/advances'),
        axios.get('http://localhost:5000/api/attendance/today')
      ])

      // Process employees data
      let employees = []
      let activeEmployees = 0
      if (employeesRes.status === 'fulfilled') {
        employees = safeExtract(employeesRes.value.data, 'employees')
        activeEmployees = employees.filter(e => e?.status === 'active').length
        setApiStatus(prev => ({ ...prev, employees: 'success' }))
      } else {
        console.error('Employees API failed:', employeesRes.reason)
